-- Step 2 of setup: a limited role and a key-only service user for the hourly job.
-- Run once in Snowflake as ACCOUNTADMIN. The public key below is not a secret;
-- the private key lives only on the owner's PC and in GitHub Secrets.

USE ROLE ACCOUNTADMIN;

-- A role that can only touch the pipeline's database
CREATE ROLE IF NOT EXISTS PIPELINE_ROLE;
GRANT USAGE ON WAREHOUSE PIPELINE_WH TO ROLE PIPELINE_ROLE;
GRANT USAGE ON DATABASE QUAKES TO ROLE PIPELINE_ROLE;
GRANT USAGE, CREATE TABLE, CREATE STAGE ON SCHEMA QUAKES.CORE TO ROLE PIPELINE_ROLE;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA QUAKES.CORE TO ROLE PIPELINE_ROLE;

-- The robot user: no password, key file only
CREATE USER IF NOT EXISTS PIPELINE_BOT
  TYPE = SERVICE
  DEFAULT_ROLE = PIPELINE_ROLE
  DEFAULT_WAREHOUSE = PIPELINE_WH
  RSA_PUBLIC_KEY = '';
GRANT ROLE PIPELINE_ROLE TO USER PIPELINE_BOT;

DESC USER PIPELINE_BOT;
